  <title>Photo Gallery | Pobrecita</title>
  <style>
    :root {
      --bg: #111;
      --surface: #1a1a1a;
      --text: #f4f4f4;
      --muted: #aaa;
      --accent: #ff4d6d;
      --shadow: rgba(0, 0, 0, 0.5);
    }

    * {
      box-sizing: border-box;
    }

    html, body {
      margin: 0;
      padding: 0;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.5;
    }

    header {
      text-align: center;
      padding: 3rem 1rem 2rem;
    }

    header h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 4rem);
      letter-spacing: -0.04em;
    }

    header p {
      margin: 0.5rem 0 0;
      color: var(--muted);
      font-size: 1.1rem;
    }

    .gallery {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 1rem;
      padding: 1rem;
      max-width: 1400px;
      margin: 0 auto;
    }

    .gallery figure {
      margin: 0;
      position: relative;
      overflow: hidden;
      border-radius: 8px;
      cursor: pointer;
      background: var(--surface);
      aspect-ratio: 4 / 3;
      box-shadow: 0 4px 12px var(--shadow);
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    .gallery figure:hover,
    .gallery figure:focus-within {
      transform: translateY(-4px);
      box-shadow: 0 8px 24px var(--shadow);
    }

    .gallery img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
      transition: transform 0.3s ease;
    }

    .gallery figure:hover img {
      transform: scale(1.05);
    }

    .gallery figcaption {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      padding: 1rem;
      background: linear-gradient(to top, rgba(0,0,0,0.85), transparent);
      color: #fff;
      font-size: 0.95rem;
      opacity: 0;
      transition: opacity 0.2s ease;
    }

    .gallery figure:hover figcaption,
    .gallery figure:focus-within figcaption {
      opacity: 1;
    }

    /* Lightbox */
    .lightbox {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.95);
      display: none;
      align-items: center;
      justify-content: center;
      z-index: 1000;
      opacity: 0;
      transition: opacity 0.25s ease;
    }

    .lightbox.active {
      display: flex;
      opacity: 1;
    }

    .lightbox img {
      max-width: 90vw;
      max-height: 85vh;
      object-fit: contain;
      border-radius: 4px;
      box-shadow: 0 0 40px rgba(0,0,0,0.6);
    }

    .lightbox-caption {
      position: absolute;
      bottom: 1.5rem;
      left: 50%;
      transform: translateX(-50%);
      color: #fff;
      text-align: center;
      font-size: 1rem;
      max-width: 80vw;
      background: rgba(0,0,0,0.5);
      padding: 0.5rem 1rem;
      border-radius: 999px;
    }

    .lightbox-close,
    .lightbox-prev,
    .lightbox-next {
      position: absolute;
      background: rgba(255,255,255,0.1);
      border: none;
      color: #fff;
      width: 44px;
      height: 44px;
      border-radius: 50%;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.2s ease;
    }

    .lightbox-close:hover,
    .lightbox-prev:hover,
    .lightbox-next:hover {
      background: var(--accent);
    }

    .lightbox-close {
      top: 1rem;
      right: 1rem;
      font-size: 1.5rem;
    }

    .lightbox-prev {
      left: 1rem;
      top: 50%;
      transform: translateY(-50%);
    }

    .lightbox-next {
      right: 1rem;
      top: 50%;
      transform: translateY(-50%);
    }

    footer {
      text-align: center;
      padding: 2rem 1rem;
      color: var(--muted);
      font-size: 0.9rem;
    }

    @media (max-width: 600px) {
      .gallery {
        grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
        gap: 0.5rem;
        padding: 0.5rem;
      }

      .lightbox-prev,
      .lightbox-next {
        display: none;
      }
    }
  </style>
</head>
<body>

  <header>
    <h1>Pobrecita</h1>
    <p>Photo gallery</p>
  </header>

  <main class="gallery" id="gallery">
    <figure tabindex="0" data-index="0" data-caption="On stage in Brooklyn">
      <img src="https://images.unsplash.com/photo-1501386761578-eac5c94b800a?auto=format&fit=crop&w=800&q=80" alt="On stage in Brooklyn" loading="lazy" />
      <figcaption>On stage in Brooklyn</figcaption>
    </figure>

    <figure tabindex="0" data-index="1" data-caption="Rehearsal room lights">
      <img src="https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=800&q=80" alt="Rehearsal room lights" loading="lazy" />
      <figcaption>Rehearsal room lights</figcaption>
    </figure>

    <figure tabindex="0" data-index="2" data-caption="Late night writing session">
      <img src="https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=800&q=80" alt="Late night writing session" loading="lazy" />
      <figcaption>Late night writing session</figcaption>
    </figure>

    <figure tabindex="0" data-index="3" data-caption="Tour van sunrise">
      <img src="https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=80" alt="Tour van sunrise" loading="lazy" />
      <figcaption>Tour van sunrise</figcaption>
    </figure>

    <figure tabindex="0" data-index="4" data-caption="Crowd sing-along">
      <img src="https://images.unsplash.com/photo-1493225255756-d9584f8606e8?auto=format&fit=crop&w=800&q=80" alt="Crowd sing-along" loading="lazy" />
      <figcaption>Crowd sing-along</figcaption>
    </figure>

    <figure tabindex="0" data-index="5" data-caption="Backstage before the set">
      <img src="https://images.unsplash.com/photo-1524368535928-5b5e00ddc76b?auto=format&fit=crop&w=800&q=80" alt="Backstage before the set" loading="lazy" />
      <figcaption>Backstage before the set</figcaption>
    </figure>

    <figure tabindex="0" data-index="6" data-caption="Acoustic living room show">
      <img src="https://images.unsplash.com/photo-1485579149621-3123dd979885?auto=format&fit=crop&w=800&q=80" alt="Acoustic living room show" loading="lazy" />
      <figcaption>Acoustic living room show</figcaption>
    </figure>

    <figure tabindex="0" data-index="7" data-caption="New demo tapes">
      <img src="https://images.unsplash.com/photo-1514320291840-2e0a9bf2a9ae?auto=format&fit=crop&w=800&q=80" alt="New demo tapes" loading="lazy" />
      <figcaption>New demo tapes</figcaption>
    </figure>
  </main>

  <div class="lightbox" id="lightbox" role="dialog" aria-modal="true" aria-label="Image preview">
    <button class="lightbox-close" aria-label="Close" id="lightbox-close">&times;</button>
    <button class="lightbox-prev" aria-label="Previous image" id="lightbox-prev">
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
    </button>
    <button class="lightbox-next" aria-label="Next image" id="lightbox-next">
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
    </button>
    <img id="lightbox-img" src="" alt="" />
    <div class="lightbox-caption" id="lightbox-caption"></div>
  </div>

  <footer>
    &copy; Pobrecita. All rights reserved.
  </footer>

  <script>
    (function() {
      const gallery = document.getElementById('gallery');
      const figures = Array.from(gallery.querySelectorAll('figure'));
      const lightbox = document.getElementById('lightbox');
      const lightboxImg = document.getElementById('lightbox-img');
      const lightboxCaption = document.getElementById('lightbox-caption');
      const closeBtn = document.getElementById('lightbox-close');
      const prevBtn = document.getElementById('lightbox-prev');
      const nextBtn = document.getElementById('lightbox-next');

      let currentIndex = 0;

      function openLightbox(index) {
        currentIndex = index;
        const figure = figures[index];
        const img = figure.querySelector('img');
        const caption = figure.getAttribute('data-caption') || img.alt;

        lightboxImg.src = img.src;
        lightboxImg.alt = img.alt;
        lightboxCaption.textContent = caption;
        lightbox.classList.add('active');
        document.body.style.overflow = 'hidden';
      }

      function closeLightbox() {
        lightbox.classList.remove('active');
        lightboxImg.src = '';
        document.body.style.overflow = '';
      }

      function showNext() {
        currentIndex = (currentIndex + 1) % figures.length;
        openLightbox(currentIndex);
      }

      function showPrev() {
        currentIndex = (currentIndex - 1 + figures.length) % figures.length;
        openLightbox(currentIndex);
      }

      figures.forEach((figure) => {
        figure.addEventListener('click', () => openLightbox(Number(figure.getAttribute('data-index'))));
        figure.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            openLightbox(Number(figure.getAttribute('data-index')));
          }
        });
      });

      closeBtn.addEventListener('click', closeLightbox);
      nextBtn.addEventListener('click', showNext);
      prevBtn.addEventListener('click', showPrev);

      lightbox.addEventListener('click', (e) => {
        if (e.target === lightbox) closeLightbox();
      });

      document.addEventListener('keydown', (e) => {
        if (!lightbox.classList.contains('active')) return;
        if (e.key === 'Escape') closeLightbox();
        if (e.key === 'ArrowRight') showNext();
        if (e.key === 'ArrowLeft') showPrev();
      });
    })();
  </script>
</body>
</html>
